import Image, { type ImageProps } from "next/image";
import { blurFor } from "@/content/image-blur";

type PhotoProps = Omit<ImageProps, "src" | "placeholder" | "blurDataURL"> & { src: string };

/**
 * next/image with Cocoya defaults: AVIF/WebP delivery, responsive sizes and a
 * tiny blurred preview (generated by `npm run images:blur`) while it loads.
 */
export function Photo({ src, alt, quality = 75, ...props }: PhotoProps) {
  const blur = blurFor(src);
  return (
    <Image
      src={src}
      alt={alt}
      quality={quality}
      placeholder={blur ? "blur" : "empty"}
      blurDataURL={blur}
      {...props}
    />
  );
}
